using System;
using UnityEngine;

namespace SickOfIt.Data.Config
{
    public enum PlatformType
    {
        Standard,
        Old,
        DropThrough
    }

    /// <summary>
    /// Defines one platform in a level.
    /// The Platform prefab is generated by PlatformPrefabGenerator
    /// and stored in GameDefinition.platformPrefab.
    /// </summary>
    [Serializable]
    public class PlatformConfig
    {
        public PlatformType type = PlatformType.Standard;

        public Vector2 position;
        public Vector2 scale = Vector2.one;

        [Tooltip("Width of the platform (sets collider and visual width)")]
        public float width = 3f;

        [Tooltip("If true, player can drop through by pressing down")]
        public bool allowDropThrough = true;
    }
}
